/* From Uiverse.io by JohnnyCSilva - Tags: notification */
.__UIV_SCOPE__ .card {
  width: 100%;
  max-width: 290px;
  height: 70px;
  background: #353535;
  border-radius: 20px;
  display: flex;
  align-items: center;
  justify-content: left;
  backdrop-filter: blur(10px);
  transition: 0.5s ease-in-out;
}

.__UIV_SCOPE__ .card:hover {
  cursor: pointer;
  transform: scale(1.05);
}

.__UIV_SCOPE__ .img {
  width: 50px;
  height: 50px;
  margin-left: 10px;
  border-radius: 10px;
  background: linear-gradient(#d7cfcf, #9198e5);
}

.__UIV_SCOPE__ .card:hover > .img {
  transition: 0.5s ease-in-out;
  background: linear-gradient(#9198e5, #712020);
}

.__UIV_SCOPE__ .textBox {
  width: calc(100% - 90px);
  margin-left: 10px;
  color: white;
  font-family: 'Poppins' sans-serif;
}

.__UIV_SCOPE__ .textContent {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.__UIV_SCOPE__ .span {
  font-size: 10px;
}

.__UIV_SCOPE__ .h1 {
  font-size: 16px;
  font-weight: bold;
}

.__UIV_SCOPE__ .p {
  font-size: 12px;
  font-weight: lighter;
}
